/**
 * Prices a provider request before it is sent, from the cost rules Treg publishes
 * in its public catalog. One evaluator covers every rule format in use:
 *
 *   table  rows of { when, value, times?, timesMin? }; the first row whose `when` matches wins
 *   unit   { value, per, unit } where unit is call | character | utf8_byte
 *   ceiling the reservation ceiling, used only when nothing matches
 *
 * `treg-catalog.json` is generated by `scripts/sync-treg-catalog.mjs`. Do not edit it by hand.
 */
import catalogJson from "./treg-catalog.json";

type Scalar = string | number | boolean;

interface CostRow {
  when: Record<string, Scalar>;
  value: number;
  times?: string;
  timesMin?: number;
}

interface Cost {
  table?: CostRow[];
  value?: number;
  per?: number;
  unit?: string;
  ceiling?: number;
  settle?: string;
}

export interface CatalogEndpoint {
  provider: string;
  platform: string | null;
  name: string;
  method: string;
  path: string;
  /** Path and query parameter names. Treg takes both in the query string. */
  params: string[];
  /** Provider headers the gateway requires, with the values it accepts ([] means any). */
  headers?: Record<string, string[]>;
  cost: Cost | null;
  /** Null for synchronous endpoints. */
  async: {
    interval: number | null;
    /** Where the provider's status word sits in its status body, and the words that end a job. */
    statusPath?: string;
    success?: string[];
    failure?: string[];
    /** Where the result sits in the provider's final status body. */
    resultPath?: string;
    /** Or: a second endpoint that returns the result. */
    fetch?: string;
    fetchParam?: { name: string; valueFrom: string };
  } | null;
}

const endpoints = (catalogJson as unknown as { endpoints: Record<string, CatalogEndpoint> }).endpoints;

export function catalogEndpoint(id: string): CatalogEndpoint | undefined {
  return endpoints[id];
}

/** Reads `a.b.c` from a value. A leading `body.` is dropped: rule paths are written from the request root. */
export function readPath(root: unknown, path: string): unknown {
  let node: unknown = root;
  for (const key of path.replace(/^body\./, "").split(".")) {
    if (node === null || typeof node !== "object") return undefined;
    node = (node as Record<string, unknown>)[key];
  }
  return node;
}

export interface Quote {
  /** What the provider will charge, in US dollars. */
  usd: number;
  /** False when no rule matched and the reservation ceiling was used. */
  exact: boolean;
  /**
   * True when the member may pay less than `usd`: the provider bills by real usage and tells us the
   * real price with the answer. Only direct answers do that. A job we have to poll for never
   * reports a final price, so it costs the quote.
   */
  metered: boolean;
}

function textLength(body: unknown, unit: string): number {
  const text = readPath(body, "text");
  if (typeof text !== "string") return 0;
  if (unit === "utf8_byte") return new TextEncoder().encode(text).length;
  // "character" counts code points, so an emoji is one character.
  return Array.from(text).length;
}

export function quoteUsd(endpointId: string, body: unknown): Quote {
  const cost = endpoints[endpointId]?.cost;
  if (!cost) return { usd: 0, exact: false, metered: false };
  const metered = cost.settle === "usage" && !endpoints[endpointId]?.async;

  for (const row of cost.table ?? []) {
    const hit = Object.entries(row.when).every(([path, want]) => String(readPath(body, path)) === String(want));
    if (!hit) continue;
    if (!row.times) return { usd: row.value, exact: true, metered };
    const n = Number(readPath(body, row.times));
    if (!Number.isFinite(n)) continue;
    return { usd: row.value * Math.max(n, row.timesMin ?? 0), exact: true, metered };
  }

  if (cost.value != null && !cost.table) {
    const per = cost.per ?? 1;
    const unit = cost.unit ?? "call";
    if (unit === "call") return { usd: cost.value / per, exact: true, metered };
    return { usd: (textLength(body, unit) * cost.value) / per, exact: true, metered };
  }

  return { usd: cost.ceiling ?? 0, exact: false, metered };
}
